/**
 * Tab 3 — Thống kê đánh giá sự cố
 *
 * Charts:
 *  • Doughnut — Mức độ nghiêm trọng (bySeverity)
 *  • Doughnut — Tình trạng xảy ra (byOccurrenceStatus)
 *  • Bar      — Số sự cố theo tháng (trend)
 *  • H-Bar    — Hình thức báo cáo
 */
import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
} from '../chartUtils';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
}

const toDoughnutData = (items: ChartDataItem[], colorOffset = 0) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: CHART_COLORS.slice(colorOffset, colorOffset + items.length),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

export const Tab3Assessment: React.FC<Props> = ({ report }) => {
  // Severity — use red/orange/green palette for impact readability
  const severityColors = ['#10b981', '#f59e0b', '#ef4444', '#94a3b8'];
  const severityDoughnut = {
    labels: report.bySeverity.map((d) => d.label),
    datasets: [
      {
        data: report.bySeverity.map((d) => d.count),
        backgroundColor: severityColors,
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
  };

  // Monthly trend bar
  const monthBarData = {
    labels: report.byMonth.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byMonth.map((d) => d.count),
        backgroundColor: report.byMonth.map((_, i) => {
          const cnt = report.byMonth[i].count;
          if (cnt === 0) return '#e2e8f0';
          const max = Math.max(...report.byMonth.map((x) => x.count), 1);
          const ratio = cnt / max;
          if (ratio > 0.66) return '#ef4444';
          if (ratio > 0.33) return '#f59e0b';
          return '#10b981';
        }),
        borderRadius: 4,
        borderSkipped: false,
      },
    ],
  };

  // Report type horizontal bar
  const reportTypeBar = {
    labels: report.byReportType.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byReportType.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byReportType.length),
        borderRadius: 4,
      },
    ],
  };

  return (
    <div>
      {/* Row 1: Severity + Occurrence doughnuts */}
      <div className={s.grid2} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-exclamation-triangle" /> Phân bố mức độ nghiêm trọng</h3>
          <Doughnut data={severityDoughnut} options={DOUGHNUT_OPTIONS} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-check-circle" /> Phân bố tình trạng xảy ra</h3>
          <Doughnut data={toDoughnutData(report.byOccurrenceStatus, 2)} options={DOUGHNUT_OPTIONS} />
        </div>
      </div>

      {/* Row 2: Monthly trend bar */}
      <div className={s.chartCard} style={{ marginBottom: 16 }}>
        <h3>
          <i className="fas fa-chart-line" />
          Xu hướng sự cố theo tháng
          <span style={{ fontSize: '0.7rem', fontWeight: 400, marginLeft: 8, color: '#64748b' }}>
            Màu sắc phản ánh mức độ: xanh lá = thấp · vàng = trung bình · đỏ = cao
          </span>
        </h3>
        <Bar data={monthBarData} options={BAR_OPTIONS_VERTICAL} />
      </div>

      {/* Row 3: Report type */}
      <div className={s.chartCard}>
        <h3><i className="fas fa-file-alt" /> Hình thức báo cáo</h3>
        <Bar data={reportTypeBar} options={BAR_OPTIONS_HORIZONTAL} />
      </div>
    </div>
  );
};
