import React from 'react';
import { Ticket } from '../../../models/Ticket';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './TicketInfo.module.css';

interface TicketInfoProps {
  ticket: Ticket;
}

const TicketInfo: React.FC<TicketInfoProps> = ({ ticket }) => {
  const { ticketCategoryOptions } = useFormOptions('display-labels');

  const getCategoryLabel = (category?: string): string => {
    if (!category) return 'Chưa phân loại';
    const opt = ticketCategoryOptions.find((o) => o.value === category.toLowerCase());
    return opt ? opt.label : category;
  };

  const getCategoryIcon = (category?: string) => {
    if (!category) return 'fas fa-question-circle';
    switch (category.toLowerCase()) {
      case 'technical':      return 'fas fa-cogs';
      case 'administrative': return 'fas fa-file-alt';
      case 'clinical':       return 'fas fa-stethoscope';
      default:               return 'fas fa-tag';
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.field}>
        <label className={styles.label}>Tiêu đề</label>
        <div className={styles.value}>{ticket.title}</div>
      </div>

      <div className={styles.field}>
        <label className={styles.label}>Mô tả</label>
        <div className={styles.description}>{ticket.description}</div>
      </div>

      <div className={styles.grid}>
        <div className={styles.field}>
          <label className={styles.label}>Danh mục</label>
          <div>
            <span className={`${styles.badge} ${styles.categoryBadge}`}>
              <i className={getCategoryIcon(ticket.category)}></i>{' '}
              {getCategoryLabel(ticket.category)}
            </span>
          </div>
        </div>

        <div className={styles.field}>
          <label className={styles.label}>Phòng ban</label>
          <div>
            <span className={`${styles.badge} ${styles.departmentBadge}`}>
              <i className="fas fa-building"></i> {ticket.departmentName}
            </span>
          </div>
        </div>
      </div>

      {ticket.tags && ticket.tags.length > 0 && (
        <div className={styles.field}>
          <label className={styles.label}>Tags</label>
          <div className={styles.tags}>
            {ticket.tags.map((tag) => (
              <span key={tag} className={`${styles.badge} ${styles.tagBadge}`}>
                {tag}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default TicketInfo;
