import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { createTask } from '../../../store/slices/tasksSlice';
import { useAppToast } from '../../../hooks/useAppToast';
import { TaskPriority, AssignmentStrategy } from '../../../models/Task';
import { Input } from '../../../components/common/Input';
import { TextArea } from '../../../components/common/TextArea';
import { Select, SelectOption } from '../../../components/common/Select';
import { Button } from '../../../components/common/Button';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { userService } from '../../../services/user';
import styles from './CreateTaskForm.module.css';

interface CreateTaskFormProps {
  onSuccess: () => void;
}

export const CreateTaskForm: React.FC<CreateTaskFormProps> = ({ onSuccess }) => {
  const dispatch = useAppDispatch();
  const toast = useAppToast();
  const [loading, setLoading] = useState(false);
  // Current authenticated user (for self-assign option)
  const currentUser = useAppSelector((state) => state.auth.user);
  const {
    loading: optLoading,
    defaultDepartmentId,
    departmentOptions,
    taskPriorityOptions,
    assignmentStrategyOptions,
  } = useFormOptions('create-task');
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    priority: TaskPriority.Medium,
    estimatedHours: 0,
    dueDate: '',
    category: '',
    departmentId: '',
    departmentName: '',
    assignmentStrategy: AssignmentStrategy.Pool,
    assigneeId: '',
    assigneeName: '',
    assignToDepartmentId: '',
    assignToDepartmentName: '',
    tags: '',
    skillsRequired: '',
  });

  /** Separate state for filtering the assignee list by department — does NOT affect task.departmentId */
  const [assigneeDeptFilter, setAssigneeDeptFilter] = useState('');

  // Pre-select the user's own department once form options are loaded.
  useEffect(() => {
    if (!optLoading && defaultDepartmentId && !formData.departmentId) {
      const selectedDept = departmentOptions.find(d => d.value === defaultDepartmentId);
      setFormData(prev => ({
        ...prev,
        departmentId: defaultDepartmentId,
        departmentName: selectedDept?.label ?? '',
      }));
    }
  }, [optLoading, defaultDepartmentId, departmentOptions, formData.departmentId]);

  // Staff candidates — fetched from /users/candidates, re-fetched when assigneeDeptFilter changes
  const [staffOptions, setStaffOptions] = useState<SelectOption[]>([]);
  const [staffLoading, setStaffLoading] = useState(false);
  /** Whether user chose to self-assign (Direct strategy only) */
  const [selfAssign, setSelfAssign] = useState(false);

  useEffect(() => {
    if (formData.assignmentStrategy !== AssignmentStrategy.Direct) return;
    let cancelled = false;
    setStaffLoading(true);
    userService
      .getCandidates(assigneeDeptFilter || undefined)
      .then((users) => {
        if (cancelled) return;
        setStaffOptions([
          { value: '', label: 'Chọn người thực hiện...' },
          ...users.map((u) => ({ value: u.id, label: `${u.fullName} — ${u.departmentName ?? ''}` })),
        ]);
      })
      .catch(() => {
        if (!cancelled) setStaffOptions([{ value: '', label: 'Chọn người thực hiện...' }]);
      })
      .finally(() => { if (!cancelled) setStaffLoading(false); });
    return () => { cancelled = true; };
  }, [formData.assignmentStrategy, assigneeDeptFilter, currentUser]);

  const handleChange = (
    field: string,
    value: string | number | TaskPriority | AssignmentStrategy
  ) => {
    // When switching to Direct assignment, pre-check self-assign by default
    if (field === 'assignmentStrategy' && value === AssignmentStrategy.Direct) {
      setSelfAssign(true);
      if (currentUser) {
        setFormData(prev => ({ ...prev, assignmentStrategy: value, assigneeId: currentUser.id, assigneeName: currentUser.fullName }));
        return;
      }
    }
    // When switching away from Direct assignment, reset self-assign + dept filter
    if (field === 'assignmentStrategy' && value !== AssignmentStrategy.Direct) {
      setSelfAssign(false);
      setAssigneeDeptFilter('');
    }
    setFormData((prev) => {
      // If changing department, update both departmentId and departmentName
      if (field === 'departmentId') {
        const selectedDept = departmentOptions.find(d => d.value === value);
        return {
          ...prev,
          departmentId: value as string,
          departmentName: selectedDept?.label || '',
        };
      }
      // If changing assignee, update both assigneeId and assigneeName
      if (field === 'assigneeId') {
        const selectedStaff = staffOptions.find(s => s.value === value);
        // Strip the dept suffix from the label (format: "Name — Dept")
        const rawLabel = selectedStaff?.label || '';
        const cleanName = rawLabel.includes(' — ') ? rawLabel.split(' — ')[0] : rawLabel;
        return {
          ...prev,
          assigneeId: value as string,
          assigneeName: cleanName,
        };
      }      // If changing assign to department, update both ID and Name
      if (field === 'assignToDepartmentId') {
        const selectedDept = departmentOptions.find(d => d.value === value);
        return {
          ...prev,
          assignToDepartmentId: value as string,
          assignToDepartmentName: selectedDept?.label || '',
        };
      }
      return { ...prev, [field]: value };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const taskData = {
        ...formData,
        estimatedHours: Number(formData.estimatedHours),
        dueDate: formData.dueDate, // keep as ISO date string; BFF accepts DateTime? via JSON string
        skillsRequired: formData.skillsRequired
          .split(',')
          .map((s) => s.trim())
          .filter((s) => s),
        tags: formData.tags
          .split(',')
          .map((t) => t.trim())
          .filter((t) => t),
      };

      await dispatch(createTask(taskData)).unwrap();
      toast.success('Tạo công việc thành công');
      onSuccess();
    } catch (error: unknown) {
      toast.fromError(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <div className={styles.formGroup}>
        <label className={styles.label}>
          Tiêu đề <span className={styles.required}>*</span>
        </label>
        <Input
          value={formData.title}
          onChange={(e) => handleChange('title', e.target.value)}
          placeholder="Nhập tiêu đề task..."
          required
        />
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Mô tả</label>
        <TextArea
          value={formData.description}
          onChange={(e) => handleChange('description', e.target.value)}
          placeholder="Mô tả chi tiết về task..."
          rows={4}
        />
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>
          Thời hạn dự kiến <span className={styles.required}>*</span>
        </label>
        <Input
          type="date"
          value={formData.dueDate}
          onChange={(e) => handleChange('dueDate', e.target.value)}
          required
        />
      </div>

      <div className={styles.formRow}>
        <div className={styles.formGroup}>
          <label className={styles.label}>
            Ưu tiên <span className={styles.required}>*</span>
          </label>
          <Select
            value={formData.priority}
            onChange={(e) => handleChange('priority', e.target.value as TaskPriority)}
            required
            options={taskPriorityOptions}
            placeholder={optLoading ? 'Đang tải...' : ''}
            disabled={optLoading}
          />
        </div>

        <div className={styles.formGroup}>
          <label className={styles.label}>Ước tính (giờ)</label>
          <Input
            type="number"
            value={formData.estimatedHours}
            onChange={(e) => handleChange('estimatedHours', e.target.value)}
            placeholder="0"
            min="0"
            step="0.5"
          />
        </div>
      </div>

      <div className={styles.formRow}>
        <div className={styles.formGroup}>
          <label className={styles.label}>Danh mục</label>
          <Input
            value={formData.category}
            onChange={(e) => handleChange('category', e.target.value)}
            placeholder="IT, Database, HR, ..."
          />
        </div>

        <div className={styles.formGroup}>
          <label className={styles.label}>Phòng ban</label>
          <Select
            value={formData.departmentId}
            onChange={(e) => handleChange('departmentId', e.target.value)}
            options={departmentOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn phòng ban...'}
            disabled={optLoading}
          />
        </div>
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Tags</label>
        <Input
          value={formData.tags}
          onChange={(e) => handleChange('tags', e.target.value)}
          placeholder="urgent, database, hardware, ... (phân cách bằng dấu phẩy)"
        />
        <small className={styles.hint}>
          <i className="fas fa-tag"></i> Phân cách các tag bằng dấu phẩy
        </small>
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Kỹ năng yêu cầu</label>
        <Input
          value={formData.skillsRequired}
          onChange={(e) => handleChange('skillsRequired', e.target.value)}
          placeholder="SQL, Network, ... (phân cách bằng dấu phẩy)"
        />
        <small className={styles.hint}>Phân cách các kỹ năng bằng dấu phẩy</small>
      </div>

      {/* Assignment Strategy Section */}
      <div className={styles.sectionDivider}></div>

      <div className={styles.formGroup}>
        <label className={styles.label}>
          Phân công <span className={styles.required}>*</span>
        </label>
        <Select
          value={formData.assignmentStrategy}
          onChange={(e) => handleChange('assignmentStrategy', e.target.value as AssignmentStrategy)}
          required
          options={assignmentStrategyOptions}
        />
      </div>

      {/* Conditional: Direct Assignment */}
      {formData.assignmentStrategy === AssignmentStrategy.Direct && (
        <>
          {/* Self-assign checkbox */}
          <div className={styles.formGroup}>
            <label className={styles.selfAssignLabel}>
              <input
                type="checkbox"
                className={styles.selfAssignCheckbox}
                checked={selfAssign}
                onChange={(e) => {
                  const checked = e.target.checked;
                  setSelfAssign(checked);
                  if (checked && currentUser) {
                    setFormData(prev => ({
                      ...prev,
                      assigneeId: currentUser.id,
                      assigneeName: currentUser.fullName,
                    }));
                  } else {
                    setFormData(prev => ({ ...prev, assigneeId: '', assigneeName: '' }));
                  }
                }}
              />
              <span>
                Tự giao cho bản thân{currentUser ? ` (${currentUser.fullName})` : ''}
              </span>
            </label>
          </div>

          {/* Dept filter + staff picker — hidden when self-assigning */}
          {!selfAssign && (
            <>
              {/* Department filter (optional) — only filters the assignee list */}
              <div className={styles.formGroup}>
                <label className={styles.label}>
                  <i className="fas fa-building"></i> Lọc theo phòng ban
                  <span className={styles.optionalHint}> (tuỳ chọn)</span>
                </label>
                <Select
                  value={assigneeDeptFilter}
                  onChange={(e) => {
                    setAssigneeDeptFilter(e.target.value);
                    setFormData((prev) => ({ ...prev, assigneeId: '', assigneeName: '' }));
                  }}
                  options={[
                    { value: '', label: 'Tất cả phòng ban' },
                    ...departmentOptions.filter(d => d.value !== ''),
                  ]}
                  placeholder={optLoading ? 'Đang tải...' : 'Tất cả phòng ban'}
                  disabled={optLoading}
                />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.label}>
                  Người thực hiện <span className={styles.required}>*</span>
                </label>
                <Select
                  value={formData.assigneeId}
                  onChange={(e) => handleChange('assigneeId', e.target.value)}
                  required
                  options={staffOptions}
                  placeholder={staffLoading ? 'Đang tải...' : 'Chọn người thực hiện...'}
                  disabled={staffLoading}
                />
              </div>
            </>
          )}
        </>
      )}

      {/* Conditional: Team Assignment - Show Department Picker */}
      {formData.assignmentStrategy === AssignmentStrategy.Team && (
        <div className={styles.formGroup}>
          <label className={styles.label}>
            Phòng ban thực hiện <span className={styles.required}>*</span>
          </label>
          <Select
            value={formData.assignToDepartmentId}
            onChange={(e) => handleChange('assignToDepartmentId', e.target.value)}
            required
            options={departmentOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn phòng ban...'}
            disabled={optLoading}
          />
        </div>
      )}

      {/* Pool Assignment - No additional field needed */}
      {formData.assignmentStrategy === AssignmentStrategy.Pool && (
        <div className={styles.infoBox}>
          <i className="fas fa-info-circle"></i>
          <span>Task sẽ được đưa vào danh mục chờ nhận. Nhân viên có thể tự chọn nhận task này.</span>
        </div>
      )}

      <div className={styles.formActions}>
        <Button type="submit" variant="primary" disabled={loading}>
          {loading ? (
            <>
              <i className="fas fa-spinner fa-spin"></i> Đang tạo...
            </>
          ) : (
            <>
              <i className="fas fa-plus"></i> Tạo Task
            </>
          )}
        </Button>
      </div>
    </form>
  );
};
