import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { assignTicket } from '../../../store/slices/ticketsSlice';
import { fetchUsers } from '../../../store/slices/usersSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { Select, SelectOption } from '../../common/Select';
import styles from './AssignTicketModal.module.css';

export interface AssignTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  ticketTitle: string;
  onClose: () => void;
  onSuccess?: () => void;
}

export const AssignTicketModal: React.FC<AssignTicketModalProps> = ({
  isOpen,
  ticketId,
  ticketTitle,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const { users } = useAppSelector((state) => state.users);
  const [selectedUserId, setSelectedUserId] = useState<string>('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!isOpen || users.length > 0) return;
    const timer = setTimeout(() => { dispatch(fetchUsers()); }, 0);
    return () => clearTimeout(timer);
  }, [isOpen, users.length, dispatch]);

  const userOptions: SelectOption[] = users.map((user) => ({
    value: user.id,
    label: `${user.fullName} - ${user.departmentName}`,
  }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedUserId) {
      dispatch(
        addToast({
          message: 'Vui lòng chọn người xử lý',
          type: 'error',
        })
      );
      return;
    }

    setLoading(true);

    try {
      const selectedUser = users.find((u) => u.id === selectedUserId);
      await dispatch(
        assignTicket({
          ticketId,
          userId:   selectedUserId as UUID,
          userName: selectedUser?.fullName ?? '',
        })
      ).unwrap();

      dispatch(
        addToast({
          message: 'Phân công phiếu yêu cầu thành công',
          type: 'success',
        })
      );

      setSelectedUserId('');
      onClose();
      if (onSuccess) {
        onSuccess();
      }
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Không thể phân công phiếu yêu cầu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setSelectedUserId('');
    onClose();
  };

  const handleConfirmAssign = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleCancel} 
      title="Phân công phiếu yêu cầu"
      width="500px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: 'Phân công',
        rightAction: handleConfirmAssign,
        rightDisabled: loading,
      }}
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.ticketInfo}>
          <p className={styles.label}>Phiếu yêu cầu:</p>
          <p className={styles.ticketTitle}>{ticketTitle}</p>
        </div>

        <div className={styles.field}>
          <label htmlFor="assignee" className={styles.label}>
            Người xử lý <span className={styles.required}>*</span>
          </label>
          <Select
            id="assignee"
            value={selectedUserId}
            onChange={(e) => setSelectedUserId(e.target.value)}
            options={userOptions}
            placeholder="Chọn người xử lý"
            disabled={loading}
          />
        </div>
      </form>
    </Slideout>
  );
};
