/**
 * Real BFF API calls for Task endpoints.
 */

import { Task, TaskFilters } from '../../models/Task';
import { PaginatedResponse, UUID } from '../../models/common';
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import { BffTaskDto, BffTaskPagedDto, BffTaskPoolStatsDto } from './responseModel';
import { mapBffTask, mapBffTaskPaged } from './mapper';
import {
  CreateTaskRequest,
  UpdateTaskRequest,
  RequestSupportRequest,
  AssignCollaboratorRequest,
  RequestReassignmentRequest,
  ApproveReassignmentRequest,
  MarkBlockedRequest,
  ApproveTaskRequest,
  RequestChangesRequest,
  CancelTaskRequest,
} from './requestModel';

const task = async (path: string) =>
  apiClient.patch<BffResponse<BffTaskDto>>(path, {}).then((r) => mapBffTask(unwrap(r)));

export const taskEndpoint = {
  getTasks: async (filters?: TaskFilters, page = 1, pageSize = 20): Promise<PaginatedResponse<Task>> => {
    const qs = new URLSearchParams({
      page: page.toString(), pageSize: pageSize.toString(),
      ...(filters?.status             && { status:             filters.status }),
      ...(filters?.priority           && { priority:           filters.priority }),
      ...(filters?.assignmentStrategy && { assignmentStrategy: filters.assignmentStrategy }),
      ...(filters?.assigneeId         && { assigneeId:         filters.assigneeId }),
      ...(filters?.search             && { search:             filters.search }),
      ...(filters?.category           && { category:           filters.category }),
      ...(filters?.ticketId           && { ticketId:           filters.ticketId }),
      ...(filters?.source             && { source:             filters.source }),
    });
    const res = await apiClient.get<BffResponse<BffTaskPagedDto>>(`/tasks?${qs}`);
    return mapBffTaskPaged(unwrap(res));
  },

  getPoolTasks: async (skills?: string[]): Promise<Task[]> => {
    const qs = new URLSearchParams();
    if (skills?.length) qs.set('skills', skills.join(','));
    const res = await apiClient.get<BffResponse<BffTaskDto[]>>(`/tasks/pool?${qs}`);
    return unwrap(res).map(mapBffTask);
  },

  getPoolStats: async (): Promise<BffTaskPoolStatsDto> => {
    const res = await apiClient.get<BffResponse<BffTaskPoolStatsDto>>('/tasks/pool/stats');
    return unwrap(res);
  },

  getTaskById: async (id: string): Promise<Task> => {
    const res = await apiClient.get<BffResponse<BffTaskDto>>(`/tasks/${id}`);
    return mapBffTask(unwrap(res));
  },

  createTask: async (data: CreateTaskRequest): Promise<Task> => {
    // Build a clean DTO — empty strings for Guid? fields break ASP.NET JSON binding
    const d = data as Record<string, unknown>;
    const payload: Record<string, unknown> = {
      title:                  d.title,
      description:            (d.description as string) ?? '',
      priority:               (d.priority as string)    ?? 'medium',
      estimatedHours:         Number(d.estimatedHours   ?? 0),
      dueDate:                d.dueDate  || undefined,
      category:               (d.category as string)    || undefined,
      assignmentStrategy:     (d.assignmentStrategy as string) ?? 'pool',
      skillsRequired:         Array.isArray(d.skillsRequired) ? d.skillsRequired : [],
      tags:                   Array.isArray(d.tags)           ? d.tags           : [],
      // Guid fields: omit empty strings — BFF Guid? cannot deserialize ""
      ticketId:               (d.ticketId               as string) || undefined,
      assigneeId:             (d.assigneeId             as string) || undefined,
      assigneeName:           (d.assigneeName           as string) || undefined,
      departmentId:           (d.departmentId           as string) || undefined,
      departmentName:         (d.departmentName         as string) || undefined,
      assignToDepartmentId:   (d.assignToDepartmentId   as string) || undefined,
      assignToDepartmentName: (d.assignToDepartmentName as string) || undefined,
    };
    const res = await apiClient.post<BffResponse<BffTaskDto>>('/tasks', payload);
    return mapBffTask(unwrap(res));
  },

  updateTask: async (id: string, data: UpdateTaskRequest): Promise<Task> => {
    const d = data as Record<string, unknown>;
    // Only send fields the BFF UpdateTaskDto actually has
    const payload: Record<string, unknown> = {
      title:          (d.title       as string) || undefined,
      description:    d.description !== undefined ? (d.description as string) : undefined,
      priority:       (d.priority    as string) || undefined,
      category:       (d.category    as string) || undefined,
      estimatedHours: d.estimatedHours != null ? Number(d.estimatedHours) : undefined,
      dueDate:        d.dueDate  || undefined,
      tags:           Array.isArray(d.tags)           ? d.tags           : undefined,
      skillsRequired: Array.isArray(d.skillsRequired) ? d.skillsRequired : undefined,
    };
    const res = await apiClient.put<BffResponse<BffTaskDto>>(`/tasks/${id}`, payload);
    return mapBffTask(unwrap(res));
  },

  claimTask: async (taskId: string): Promise<Task> => task(`/tasks/${taskId}/claim`),

  updateTaskStatus: async (taskId: UUID, status: string): Promise<Task> => {
    const res = await apiClient.patch<BffResponse<BffTaskDto>>(`/tasks/${taskId}/status`, { status });
    return mapBffTask(unwrap(res));
  },

  updateProgress: async (taskId: string, progress: number, note?: string): Promise<Task> => {
    const res = await apiClient.patch<BffResponse<BffTaskDto>>(`/tasks/${taskId}/progress`, { progress, ...(note ? { note } : {}) });
    return mapBffTask(unwrap(res));
  },

  submitForReview:   async (taskId: string): Promise<Task> => task(`/tasks/${taskId}/submit`),
  completeTask:      async (taskId: string): Promise<Task> => task(`/tasks/${taskId}/complete`),
  unblockTask:       async (taskId: string): Promise<Task> => task(`/tasks/${taskId}/unblock`),
  startTask:         async (taskId: string): Promise<Task> => task(`/tasks/${taskId}/start`),

  requestSupport: async (taskId: string, req: RequestSupportRequest): Promise<Task> => {
    const res = await apiClient.post<BffResponse<BffTaskDto>>(`/tasks/${taskId}/support-request`, req);
    return mapBffTask(unwrap(res));
  },

  assignCollaborator: async (taskId: string, req: AssignCollaboratorRequest): Promise<Task> => {
    const res = await apiClient.post<BffResponse<BffTaskDto>>(`/tasks/${taskId}/collaborators`, req);
    return mapBffTask(unwrap(res));
  },

  requestReassignment: async (taskId: string, req: RequestReassignmentRequest): Promise<Task> => {
    const res = await apiClient.post<BffResponse<BffTaskDto>>(`/tasks/${taskId}/reassign-request`, req);
    return mapBffTask(unwrap(res));
  },

  approveReassignment: async (taskId: string, req: ApproveReassignmentRequest): Promise<Task> => {
    const res = await apiClient.post<BffResponse<BffTaskDto>>(`/tasks/${taskId}/reassign-approve`, req);
    return mapBffTask(unwrap(res));
  },

  markBlocked: async (taskId: string, req: MarkBlockedRequest): Promise<Task> => {
    const res = await apiClient.patch<BffResponse<BffTaskDto>>(`/tasks/${taskId}/block`, req);
    return mapBffTask(unwrap(res));
  },

  approveTask: async (taskId: string, req: ApproveTaskRequest): Promise<Task> => {
    const res = await apiClient.patch<BffResponse<BffTaskDto>>(`/tasks/${taskId}/approve`, req);
    return mapBffTask(unwrap(res));
  },

  requestChanges: async (taskId: string, req: RequestChangesRequest): Promise<Task> => {
    const res = await apiClient.patch<BffResponse<BffTaskDto>>(`/tasks/${taskId}/request-changes`, req);
    return mapBffTask(unwrap(res));
  },

  cancelTask: async (taskId: string, req: CancelTaskRequest): Promise<Task> => {
    const res = await apiClient.delete<BffResponse<BffTaskDto>>(`/tasks/${taskId}`, req);
    // BFF may return the cancelled task or just 204; handle both
    return res ? mapBffTask(unwrap(res as BffResponse<BffTaskDto>)) : ({} as Task);
  },

  getDepartmentTasks: async (departmentId: UUID): Promise<Task[]> => {
    const res = await apiClient.get<BffResponse<BffTaskDto[]>>(`/tasks/department/${departmentId}`);
    return unwrap(res).map(mapBffTask);
  },

  claimDepartmentTask: async (taskId: UUID): Promise<Task> =>
    task(`/tasks/${taskId}/claim-from-department`),

  // ── Subtasks (checklist) ──────────────────────────────────────────────────
  getSubtasks: async (taskId: string): Promise<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }[]> => {
    const res = await apiClient.get<BffResponse<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }[]>>(`/tasks/${taskId}/subtasks`);
    return unwrap(res);
  },

  addSubtask: async (taskId: string, title: string, sortOrder?: number): Promise<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }> => {
    const res = await apiClient.post<BffResponse<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }>>(`/tasks/${taskId}/subtasks`, { title, sortOrder: sortOrder ?? 0 });
    return unwrap(res);
  },

  updateSubtask: async (taskId: string, subtaskId: string, data: { title?: string; completed?: boolean; sortOrder?: number }): Promise<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }> => {
    const res = await apiClient.patch<BffResponse<{ id: string; title: string; completed: boolean; completedAt?: string; sortOrder: number }>>(`/tasks/${taskId}/subtasks/${subtaskId}`, data);
    return unwrap(res);
  },

  deleteSubtask: async (taskId: string, subtaskId: string): Promise<void> => {
    await apiClient.delete(`/tasks/${taskId}/subtasks/${subtaskId}`, undefined);
  },
};
