import React from 'react';
import { Task, TaskPriority } from '../../../models/Task';
import { Badge } from '../../../components/common/Badge';
import { SLABadge } from '../../../components/common/SLABadge';
import { TwoLineTable, TwoLineTableColumn, TwoLineTableRow } from '../../../components/common/TwoLineTable';
import { format } from 'date-fns';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './TaskTable.module.css';
import { useResponsive } from '@/hooks/useResponsive';

interface TaskTableProps {
  tasks: Task[];
  loading: boolean;
  onTaskClick: (task: Task) => void;
}

export const TaskTable: React.FC<TaskTableProps> = ({
  tasks,
  loading,
  onTaskClick,
}) => {
  const { isMobile } = useResponsive();
  const { taskPriorityOptions, taskStatusOptions } = useFormOptions('display-labels');

  const getPriorityVariant = (priority: TaskPriority) => {
    switch (priority) {
      case TaskPriority.Critical: return 'danger' as const;
      case TaskPriority.High:     return 'warning' as const;
      case TaskPriority.Medium:   return 'info' as const;
      case TaskPriority.Low:      return 'success' as const;
      default:                    return 'secondary' as const;
    }
  };

  const getStatusVariant = (status: string) => {
    switch (status) {
      case 'created':      return 'secondary' as const;
      case 'assigned':     return 'info' as const;
      case 'in_progress':  return 'primary' as const;
      case 'under_review': return 'warning' as const;
      case 'completed':    return 'success' as const;
      default:             return 'secondary' as const;
    }
  };

  const getPriorityBadge = (priority: TaskPriority) => {
    const label = taskPriorityOptions.find((o) => o.value === priority)?.label ?? priority;
    return <Badge variant={getPriorityVariant(priority)}><i className={`fas fa-${priority === TaskPriority.Critical ? 'exclamation-circle' : priority === TaskPriority.High ? 'exclamation' : priority === TaskPriority.Medium ? 'minus' : 'arrow-down'}`}></i> {label}</Badge>;
  };

  const getStatusBadge = (status: string) => {
    const label = taskStatusOptions.find((o) => o.value === status)?.label ?? status;
    return <Badge variant={getStatusVariant(status)}>{label}</Badge>;
  };

  const getSLAStatus = (slaRemaining?: number) => {
    if (!slaRemaining) return 'safe';
    if (slaRemaining < 60) return 'danger';
    if (slaRemaining < 240) return 'warning';
    return 'safe';
  };

  const formatSLATime = (minutes?: number): string => {
    if (!minutes) return 'N/A';
    if (minutes < 60) return `${minutes}m`;
    if (minutes < 1440) return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
    return `${Math.floor(minutes / 1440)} ngày`;
  };

  const formatDueDate = (date: string): string => {
    if (!date) return 'N/A';
    const dueDate = new Date(date);
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    if (dueDate.toDateString() === today.toDateString()) {
      return 'Hôm nay';
    } else if (dueDate.toDateString() === tomorrow.toDateString()) {
      return 'Ngày mai';
    } else {
      return format(dueDate, 'dd/MM');
    }
  };

  // Define table columns
  const columns: TwoLineTableColumn[] = [
    { key: 'progress', label: 'Tiến độ', width: '25%' },
    { key: 'priority', label: 'Ưu tiên', width: '25%' },
    { key: 'sla', label: 'SLA', width: '25%' },
    { key: 'deadline', label: 'Thời hạn dự kiến', width: '25%' },
  ];

  // Transform tasks to table rows
  const rows: TwoLineTableRow<Task>[] = tasks.map((task) => ({
    id: task.id,
    data: task,
    line1Content: (
      <>
        <span className={styles.line1CellItem}>
          <strong className={styles.taskId}>{task.taskNumber || task.id.substring(0, 8)}</strong>
        </span>
        <span className={`${styles.line1CellItem} ${styles.taskTitle}`}>
          {task.title}
        </span>
        <span className={styles.line1CellItem}>{getStatusBadge(task.status)}</span>
      </>
    ),
    line2Cells: [
      // Progress
      <div className={styles.progressSection}>
        <div className={styles.progressBar}>
          <div
            className={styles.progressFill}
            style={{ width: `${task.progress}%` }}
          ></div>
        </div>
        <span className={styles.progressLabel}>{task.progress}%</span>
      </div>,
      // Priority
      getPriorityBadge(task.priority),
      // SLA
      <SLABadge
        status={getSLAStatus(task.slaRemaining)}
        timeRemaining={formatSLATime(task.slaRemaining)}
      />,
      // Deadline
      <>
        <i className="fas fa-calendar"></i> {formatDueDate(task.dueDate)}
      </>,
    ],
  }));

  return (
    <TwoLineTable
      columns={columns}
      rows={rows}
      loading={loading}
      emptyMessage={{
        icon: 'fas fa-inbox',
        title: 'Không có task nào',
      }}
      onRowClick={onTaskClick}
      isMobile={isMobile}
    />
  );
};
