import React, { useState, useRef, useEffect } from 'react';
import { UUID } from '../../../models/common';
import { Button } from '../../common/Button';
import { useAlert } from '../../common/Alert';
import { useAppToast } from '../../../hooks/useAppToast';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import { MentionInput, MentionInputRef } from '../MentionInput';
import { MentionText } from '../MentionText';
import { ReactionPicker, Reaction } from '../ReactionPicker';
import { TabSlideout } from '../TabSlideout';
import styles from './CommentsTab.module.css';

export interface Comment {
  id: UUID;
  entityId: UUID; // Can be ticketId or taskId
  author: string;
  authorId: string;
  authorAvatar?: string;
  content: string;
  createdAt: string;
  updatedAt?: string;
  reactions?: Reaction[];
  replies?: Comment[];
  parentId?: UUID; // For nested replies
}

export interface CommentsTabProps {
  entityId: UUID;
  entityType: 'ticket' | 'task';
  comments?: Comment[];
  onAddComment?: (content: string, parentId?: UUID) => Promise<void>;
  onEditComment?: (commentId: UUID, content: string) => Promise<void>;
  onDeleteComment?: (commentId: UUID) => Promise<void>;
  onReact?: (commentId: UUID, emoji: string) => Promise<void>;
  onUnreact?: (commentId: UUID, emoji: string) => Promise<void>;
  currentUserId?: string; // Current logged-in user ID to align comments
  hasMore?: boolean;
  loading?: boolean;
  onLoadMore?: () => Promise<void>;
}

export const CommentsTab: React.FC<CommentsTabProps> = ({
  entityId: _entityId,
  entityType: _entityType,
  comments = [],
  onAddComment,
  onEditComment,
  onDeleteComment,
  onReact,
  onUnreact,
  currentUserId = 'user-001', // Default for demo, should come from auth context
  hasMore = false,
  loading = false,
  onLoadMore,
}) => {
  const alert = useAlert();
  const toast = useAppToast();
  const [newComment, setNewComment] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [editingId, setEditingId] = useState<UUID | null>(null);
  const [editContent, setEditContent] = useState('');
  const [replyingTo, setReplyingTo] = useState<UUID | null>(null);
  const [replyContent, setReplyContent] = useState('');
  const [expandedReplies, setExpandedReplies] = useState<Set<UUID>>(new Set());
  const [loadingMore, setLoadingMore] = useState(false);
  const commentInputRef = useRef<MentionInputRef>(null);
  const commentsListRef = useRef<HTMLDivElement>(null);
  const isAtBottomRef = useRef(true);
  const touchStartYRef = useRef(0);
  // Scroll-triggered reveal (same pattern as ChatTab)
  const revealedCommentIdsRef = useRef(new Set<string>());
  const [revealedCommentIds, setRevealedCommentIds] = useState(new Set<string>());

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    const el = commentsListRef.current;
    if (el) el.scrollTo({ top: el.scrollHeight, behavior });
  };

  // Scroll + touch-swipe load more (older comments appear at top when prepended)
  useEffect(() => {
    const el = commentsListRef.current;
    if (!el) return;

    const onScroll = async () => {
      isAtBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
      if (el.scrollTop === 0 && hasMore && !loading && !loadingMore && onLoadMore) {
        const prevHeight = el.scrollHeight;
        setLoadingMore(true);
        try {
          await onLoadMore();
          requestAnimationFrame(() => {
            if (commentsListRef.current) {
              commentsListRef.current.scrollTop = commentsListRef.current.scrollHeight - prevHeight;
            }
          });
        } finally {
          setLoadingMore(false);
        }
      }
    };

    const onTouchStart = (e: TouchEvent) => {
      touchStartYRef.current = e.touches[0].clientY;
    };

    const onTouchEnd = async (e: TouchEvent) => {
      const deltaY = e.changedTouches[0].clientY - touchStartYRef.current;
      // Swipe DOWN (finger moves down) while at top = load older comments
      if (deltaY > 50 && el.scrollTop === 0 && hasMore && !loading && !loadingMore && onLoadMore) {
        const prevHeight = el.scrollHeight;
        setLoadingMore(true);
        try {
          await onLoadMore();
          requestAnimationFrame(() => {
            if (commentsListRef.current) {
              commentsListRef.current.scrollTop = commentsListRef.current.scrollHeight - prevHeight;
            }
          });
        } finally {
          setLoadingMore(false);
        }
      }
    };

    el.addEventListener('scroll', onScroll);
    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('touchend', onTouchEnd, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('touchend', onTouchEnd);
    };
  }, [hasMore, loading, loadingMore, onLoadMore]);

  // Auto-scroll to bottom when new comments arrive (only when already near bottom)
  useEffect(() => {
    if (isAtBottomRef.current) scrollToBottom();
  }, [comments]);

  // Initial scroll to bottom
  useEffect(() => {
    scrollToBottom('instant' as ScrollBehavior);
  }, []);

  // IntersectionObserver reveal — same 120px lookahead as ChatTab.
  // expandedReplies in deps: when the user expands a reply section, re-run so
  // the newly-visible reply elements are also observed and revealed on scroll.
  useEffect(() => {
    const container = commentsListRef.current;
    if (!container) return;

    const observer = new IntersectionObserver(
      (entries) => {
        const newIds: string[] = [];
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const id = (entry.target as HTMLElement).dataset.commentId;
            if (id && !revealedCommentIdsRef.current.has(id)) {
              newIds.push(id);
              revealedCommentIdsRef.current.add(id);
            }
            observer.unobserve(entry.target);
          }
        });
        if (newIds.length > 0) setRevealedCommentIds(new Set(revealedCommentIdsRef.current));
      },
      { root: container, rootMargin: '120px 0px 0px 0px', threshold: 0 },
    );

    container.querySelectorAll<HTMLElement>('[data-comment-id]').forEach((el) => {
      if (!revealedCommentIdsRef.current.has(el.dataset.commentId!)) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [comments, expandedReplies]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    setSubmitting(true);
    try {
      if (onAddComment) {
        await onAddComment(newComment.trim());
      }
      setNewComment('');
      // Auto-focus input after sending
      setTimeout(() => commentInputRef.current?.focus(), 0);
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể gửi bình luận, vui lòng thử lại');
    } finally {
      setSubmitting(false);
    }
  };

  const handleReplySubmit = async (parentId: UUID) => {
    if (!replyContent.trim()) return;

    try {
      if (onAddComment) {
        await onAddComment(replyContent.trim(), parentId);
      }
      setReplyContent('');
      setReplyingTo(null);
      // Auto-expand replies after adding
      setExpandedReplies((prev) => new Set(prev).add(parentId));
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể gửi phản hồi, vui lòng thử lại');
    }
  };

  const handleEdit = async (commentId: UUID) => {
    if (!editContent.trim()) return;

    try {
      if (onEditComment) {
        await onEditComment(commentId, editContent.trim());
      }
      setEditingId(null);
      setEditContent('');
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể chỉnh sửa bình luận, vui lòng thử lại');
    }
  };

  const handleDelete = async (commentId: UUID) => {
    alert.confirm(
      'Bạn có chắc muốn xóa comment này?',
      async () => {
        try {
          if (onDeleteComment) {
            await onDeleteComment(commentId);
          }
        } catch (error: unknown) {
          toast.fromError(error, 'Không thể xóa bình luận, vui lòng thử lại');
          alert.error('Không thể xóa comment. Vui lòng thử lại.');
        }
      }
    );
  };

  const handleReact = async (commentId: UUID, emoji: string) => {
    try {
      if (onReact) {
        await onReact(commentId, emoji);
      }
    } catch (error: unknown) {
      toast.fromError(error, 'Đã có lỗi xảy ra, vui lòng thử lại');
    }
  };

  const handleUnreact = async (commentId: UUID, emoji: string) => {
    try {
      if (onUnreact) {
        await onUnreact(commentId, emoji);
      }
    } catch (error: unknown) {
      toast.fromError(error, 'Đã có lỗi xảy ra, vui lòng thử lại');
    }
  };

  const toggleReplies = (commentId: UUID) => {
    setExpandedReplies((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(commentId)) {
        newSet.delete(commentId);
      } else {
        newSet.add(commentId);
      }
      return newSet;
    });
  };

  const formatTimeAgo = (dateString: string) => {
    return formatDistanceToNow(new Date(dateString), { addSuffix: true, locale: vi });
  };

  const getAvatarColor = (name: string) => {
    const colors = [
      '#3b82f6',
      '#8b5cf6',
      '#ec4899',
      '#f59e0b',
      '#10b981',
      '#06b6d4',
      '#6366f1',
    ];
    const index = name.charCodeAt(0) % colors.length;
    return colors[index];
  };

  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  const startEdit = (comment: Comment) => {
    setEditingId(comment.id);
    setEditContent(comment.content);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditContent('');
  };

  const cancelReply = () => {
    setReplyingTo(null);
    setReplyContent('');
  };

  const renderComment = (comment: Comment, isReply = false) => {
    const isOwnComment = comment.authorId === currentUserId;
    return (
      <div
        key={comment.id}
        data-comment-id={comment.id}
        className={`${styles.comment} ${isReply ? styles.reply : ''} ${isOwnComment ? styles.commentOwn : styles.commentOther}${revealedCommentIds.has(comment.id) ? ` ${styles.commentRevealed}` : ''}`}
      >
        {!isOwnComment && (
          <div
            className={styles.avatar}
            style={{ backgroundColor: getAvatarColor(comment.author) }}
          >
            {getInitials(comment.author)}
          </div>
        )}
        <div className={styles.commentBody}>
          {!isOwnComment && (
            <div className={styles.commentHeader}>
              <span className={styles.author}>{comment.author}</span>
              <span className={styles.timestamp}>{formatTimeAgo(comment.createdAt)}</span>
              {comment.updatedAt && comment.updatedAt !== comment.createdAt && (
                <span className={styles.edited} title="Đã chỉnh sửa">
                  <i className="fas fa-pencil-alt"></i>
                </span>
              )}
            </div>
          )}
        {editingId === comment.id ? (
          <div className={styles.editMode}>
            <MentionInput
              value={editContent}
              onChange={setEditContent}
              placeholder="Chỉnh sửa comment..."
              rows={3}
            />
            <div className={styles.editActions}>
              <Button size="sm" onClick={() => handleEdit(comment.id)}>
                <i className="fas fa-save"></i> Lưu
              </Button>
              <Button size="sm" variant="secondary" onClick={cancelEdit}>
                <i className="fas fa-times"></i> Hủy
              </Button>
            </div>
          </div>
        ) : (
          <>
            <div className={styles.commentContent}>
              <MentionText text={comment.content} />
              {isOwnComment && (
                <span className={styles.ownTimestamp}>
                  {formatTimeAgo(comment.createdAt)}
                  {comment.updatedAt && comment.updatedAt !== comment.createdAt && (
                    <i className="fas fa-pencil-alt" style={{ marginLeft: '0.25rem' }} title="Đã chỉnh sửa"></i>
                  )}
                </span>
              )}
            </div>
            
            {/* Reactions */}
            {onReact && onUnreact && (
              <ReactionPicker
                reactions={comment.reactions || []}
                onReact={(emoji) => handleReact(comment.id, emoji)}
                onUnreact={(emoji) => handleUnreact(comment.id, emoji)}
              />
            )}

            <div className={styles.commentActions}>
              {!isReply && (
                <button
                  className={styles.actionBtn}
                  onClick={() => setReplyingTo(comment.id)}
                >
                  <i className="fas fa-reply"></i> Trả lời
                </button>
              )}
              <button className={styles.actionBtn} onClick={() => startEdit(comment)}>
                <i className="fas fa-edit"></i> Sửa
              </button>
              <button className={styles.actionBtn} onClick={() => handleDelete(comment.id)}>
                <i className="fas fa-trash"></i> Xóa
              </button>
            </div>
          </>
        )}

        {/* Reply form */}
        {replyingTo === comment.id && (
          <div className={styles.replyForm}>
            <MentionInput
              value={replyContent}
              onChange={setReplyContent}
              placeholder={`Trả lời @${comment.author}...`}
              rows={2}
            />
            <div className={styles.replyActions}>
              <Button size="sm" onClick={() => handleReplySubmit(comment.id)}>
                <i className="fas fa-paper-plane"></i> Gửi
              </Button>
              <Button size="sm" variant="secondary" onClick={cancelReply}>
                <i className="fas fa-times"></i> Hủy
              </Button>
            </div>
          </div>
        )}

        {/* Replies */}
        {comment.replies && comment.replies.length > 0 && (
          <div className={styles.repliesSection}>
            <button
              className={styles.toggleReplies}
              onClick={() => toggleReplies(comment.id)}
            >
              <i className={`fas fa-chevron-${expandedReplies.has(comment.id) ? 'up' : 'down'}`}></i>
              {expandedReplies.has(comment.id) ? 'Ẩn' : 'Hiện'} {comment.replies.length} câu trả lời
            </button>
            
            {expandedReplies.has(comment.id) && (
              <div className={styles.repliesList}>
                {comment.replies.map((reply) => renderComment(reply, true))}
              </div>
            )}
          </div>
        )}
        </div>
      </div>
    );
  };

  const footerContent = (
    <form onSubmit={handleSubmit} className={styles.commentForm}>
      <div className={styles.formBody}>
        <MentionInput
          ref={commentInputRef}
          value={newComment}
          onChange={setNewComment}
          placeholder="Viết comment..."
          rows={3}
          disabled={submitting}
          onSubmit={() => handleSubmit({ preventDefault: () => {} } as React.FormEvent)}
        />
        <div className={styles.formActions}>
          <div className={styles.hints}>
            <span className={styles.hint}>
              <i className="fas fa-at"></i> @ để mention người dùng
            </span>
            <span className={styles.hint}>
              <i className="fas fa-keyboard"></i> Enter để gửi
            </span>
          </div>
          <Button type="submit" disabled={!newComment.trim() || submitting}>
            {submitting ? (
              <>
                <i className="fas fa-spinner fa-spin"></i> Đang gửi...
              </>
            ) : (
              <>
                <i className="fas fa-paper-plane"></i> Gửi Comment
              </>
            )}
          </Button>
        </div>
      </div>
    </form>
  );

  return (
    <TabSlideout footer={footerContent} className={styles.commentsTab} tabContentMaxHeight='500px'>
      {/* Comment List */}
      <div className={styles.commentsList} ref={commentsListRef}>
        {/* Pull-to-load-more indicator at top */}
        {(loadingMore || (hasMore && !loading)) && (
          <div className={styles.loadMoreContainer}>
            <span className={styles.loadMoreIndicator}>
              {loadingMore ? (
                <>
                  <span className={styles.dotsSpinner}>
                    <span className={styles.dot} />
                    <span className={styles.dot} />
                    <span className={styles.dot} />
                  </span>
                  Đang tải thêm...
                </>
              ) : (
                <>
                  <i className="fas fa-arrow-up" />
                  {' '}Cuộn lên hoặc vuốt xuống để tải thêm
                </>
              )}
            </span>
          </div>
        )}
        {comments.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-comments fa-3x"></i>
            <p>Chưa có comment nào</p>
          </div>
        ) : (
          // Only render top-level comments (no parentId)
          comments
            .filter((c) => !c.parentId)
            .map((comment) => renderComment(comment))
        )}
      </div>
    </TabSlideout>
  );
};
