/**
 * Medical Incident Service.
 */
import type {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
} from '../../models/MedicalIncident';
import type { PagedResult } from './endpoint';
import { medicalIncidentEndpoint } from './endpoint';

export const medicalIncidentService = {
  getList: (
    filters: MedicalIncidentFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PagedResult<MedicalIncident>> =>
    medicalIncidentEndpoint.getList(filters, page, pageSize),

  getStats: (): Promise<MedicalIncidentStats> =>
    medicalIncidentEndpoint.getStats(),

  getById: (id: string): Promise<MedicalIncident | null> =>
    medicalIncidentEndpoint.getById(id),

  create: (data: Partial<MedicalIncident>): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.create(data),

  update: (id: string, data: Partial<MedicalIncident>): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.update(id, data),

  delete: (id: string): Promise<void> =>
    medicalIncidentEndpoint.delete(id),

  startAnalysis: (id: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.startAnalysis(id),

  submitAnalysis: (id: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.submitAnalysis(id),

  submitFeedback: (id: string, rating: number, feedback: string): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.submitFeedback(id, rating, feedback),

  toggleServiceMismatch: (id: string, isServiceMismatch: boolean): Promise<MedicalIncident> =>
    medicalIncidentEndpoint.toggleServiceMismatch(id, isServiceMismatch),

  getReport: (filters: MedicalIncidentReportFilters): Promise<MedicalIncidentReport> =>
    medicalIncidentEndpoint.getReport(filters),
};
