import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { fetchPoolTasks, fetchPoolTaskStats, claimTask } from '../../store/slices/tasksSlice';
import { Task, TaskPriority } from '../../models/Task';
import { Badge } from '../../components/common/Badge';
import { Button } from '../../components/common/Button';
import { SLABadge } from '../../components/common/SLABadge';
import { Pagination } from '../../components/common/Pagination';
import { TableCard } from '../../components/common/TableCard';
import { useAppToast } from '../../hooks/useAppToast';
import { useResponsive } from '../../hooks/useResponsive';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import ClaimTaskModal from '../../components/task/ClaimTaskModal';
import { TaskPoolStatsCards } from './components/TaskPoolStatsCards';
import { TaskPoolFilters, TaskPoolFilterValues } from './components/TaskPoolFilters';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './TaskPoolPage.module.css';

const PAGE_SIZE = 12;

const TaskPoolPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const toast = useAppToast();
  const { isMobile } = useResponsive();
  const { poolTasks, poolStats, loading } = useAppSelector((state) => state.tasks);
  const currentUser = useAppSelector((state) => state.auth.user);
  const showLoading = useMinLoadingTime(loading);

  const [filters, setFilters] = useState<TaskPoolFilterValues>({
    priority: 'all',
    skills: 'all',
    deadline: 'all',
    sort: 'priority',
    showMyCreated: false,
  });
  const [activeStatFilter, setActiveStatFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [claiming, setClaiming] = useState(false);
  const [expandedCardId, setExpandedCardId] = useState<string | null>(null);

  const { taskPriorityOptions } = useFormOptions('task-pool');

  useEffect(() => {
    const timer = setTimeout(() => {
      dispatch(fetchPoolTasks());
      dispatch(fetchPoolTaskStats());
    }, 0);
    return () => clearTimeout(timer);
  }, [dispatch]);

  // ─── Client-side filtering & sorting ─────────────────────────────────────
  const filteredTasks = useMemo(() => {
    let result = [...poolTasks];

    if (filters.showMyCreated && currentUser) {
      result = result.filter((t) => t.creatorId === currentUser.id);
    }

    if (filters.priority !== 'all') {
      result = result.filter((t) => t.priority === filters.priority);
    }

    if (filters.skills !== 'all') {
      result = result.filter((t) =>
        t.skillsRequired?.some((s) => s === filters.skills)
      );
    }

    if (filters.deadline !== 'all') {
      const now = new Date();
      result = result.filter((t) => {
        const diffHours = (new Date(t.dueDate).getTime() - now.getTime()) / (1000 * 60 * 60);
        switch (filters.deadline) {
          case 'today': return diffHours <= 24;
          case 'week':  return diffHours <= 168;
          case 'month': return diffHours <= 720;
          default:      return true;
        }
      });
    }

    result.sort((a, b) => {
      const priorityOrder: Record<TaskPriority, number> = {
        [TaskPriority.Critical]: 0,
        [TaskPriority.High]:     1,
        [TaskPriority.Medium]:   2,
        [TaskPriority.Low]:      3,
      };
      switch (filters.sort) {
        case 'priority': return priorityOrder[a.priority] - priorityOrder[b.priority];
        case 'deadline': return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
        case 'estimate': return a.estimatedHours - b.estimatedHours;
        case 'newest':   return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        default:         return 0;
      }
    });

    return result;
  }, [poolTasks, filters, currentUser]);

  // ─── Client-side pagination ───────────────────────────────────────────────
  const pagedTasks = useMemo(
    () => filteredTasks.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [filteredTasks, currentPage]
  );

  const totalPages = Math.ceil(filteredTasks.length / PAGE_SIZE);

  // Reset to first page when filters change
  useEffect(() => { setCurrentPage(1); }, [filters]);

  // ─── Handlers ────────────────────────────────────────────────────────────
  const handleFilterChange = (newFilters: TaskPoolFilterValues) => {
    setFilters(newFilters);
    // Keep stat-card highlight in sync when priority is changed via dropdown
    if (newFilters.priority !== filters.priority) {
      setActiveStatFilter(newFilters.priority ?? 'all');
    }
  };

  const handleStatCardClick = (priority: string) => {
    setActiveStatFilter(priority);
    setFilters((prev) => ({ ...prev, priority }));
  };

  const handleCardClick = (taskId: string) => {
    setExpandedCardId((prev) => (prev === taskId ? null : taskId));
  };

  const handleOpenClaimModal = (task: Task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedTask(null);
  };

  const handleConfirmClaim = async () => {
    if (!selectedTask) return;
    setClaiming(true);
    try {
      await dispatch(claimTask(selectedTask.id)).unwrap();
      toast.success('Nhận công việc thành công!');
      handleCloseModal();
      navigate(`/tasks/${selectedTask.id}`);
    } catch (error: unknown) {
      toast.fromError(error, 'Không thể nhận task. Vui lòng thử lại!');
    } finally {
      setClaiming(false);
    }
  };

  const handleViewDetails = (taskId: string) => navigate(`/tasks/${taskId}`);

  // ─── Helpers ──────────────────────────────────────────────────────────────
  const getPriorityBadgeVariant = (priority: TaskPriority) => {
    switch (priority) {
      case TaskPriority.Critical: return 'danger';
      case TaskPriority.High:     return 'warning';
      case TaskPriority.Medium:   return 'info';
      case TaskPriority.Low:      return 'success';
    }
  };

  const getPriorityLabel = (priority: TaskPriority): string =>
    taskPriorityOptions.find((o) => o.value === priority)?.label ?? priority;

  const getSLAStatus = (slaRemaining?: number) => {
    if (!slaRemaining) return 'safe';
    if (slaRemaining < 60)  return 'danger';
    if (slaRemaining < 240) return 'warning';
    return 'safe';
  };

  const formatSLATime = (minutes?: number): string => {
    if (!minutes)       return 'N/A';
    if (minutes < 60)   return `${minutes}m`;
    if (minutes < 1440) return `${Math.floor(minutes / 60)}h`;
    return `${Math.floor(minutes / 1440)} ngày`;
  };

  const formatTimeInPool = (createdAt: string): string =>
    formatDistanceToNow(new Date(createdAt), { locale: vi, addSuffix: false });

  // ─── Render ───────────────────────────────────────────────────────────────
  return (
    <div className={styles.page}>

      {/* Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-layer-group" />
          {!isMobile ? 'Kho Công Việc - Tự Chọn' : 'Kho Công Việc'}
        </h1>
      </div>

      {/* Stats Cards */}
      <TaskPoolStatsCards
        stats={poolStats}
        loading={poolStats.loading}
        activeFilter={activeStatFilter}
        onFilter={handleStatCardClick}
      />

      {/* Main Content Card */}
      <TableCard
        header={<TaskPoolFilters filters={filters} onChange={handleFilterChange} />}
        footer={
          !loading && filteredTasks.length > 0 ? (
            <Pagination
              currentPage={currentPage}
              totalPages={totalPages}
              totalCount={filteredTasks.length}
              pageSize={PAGE_SIZE}
              onPageChange={setCurrentPage}
            />
          ) : undefined
        }
      >
        {showLoading ? (
          <div className={styles.skeletonGrid}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className={styles.skeletonCard}>
                <div className={styles.skeletonPulse} style={{ width: '40%', height: 12 }} />
                <div className={styles.skeletonPulse} style={{ width: '80%', height: 18, marginTop: 8 }} />
                <div className={styles.skeletonPulse} style={{ width: '90%', height: 14, marginTop: 6 }} />
                <div className={styles.skeletonPulse} style={{ width: '60%', height: 14, marginTop: 4 }} />
                <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
                  <div className={styles.skeletonPulse} style={{ flex: 1, height: 32, borderRadius: 6 }} />
                  <div className={styles.skeletonPulse} style={{ width: 40, height: 32, borderRadius: 6 }} />
                </div>
              </div>
            ))}
          </div>
        ) : filteredTasks.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-inbox" />
            <h3>Không có công việc nào</h3>
            <p>Hiện tại không có công việc phù hợp với bộ lọc của bạn.</p>
          </div>
        ) : (
          <div className={styles.gridBody}>
            <div className={styles.tasksGrid}>
              {pagedTasks.map((task) => (
                <div
                  key={task.id}
                  className={`${styles.taskCard} ${expandedCardId === task.id ? styles.expanded : ''}`}
                  style={{
                    borderLeftColor:
                      task.priority === TaskPriority.Critical
                        ? 'var(--danger-color)'
                        : task.priority === TaskPriority.High
                        ? 'var(--warning-color)'
                        : 'var(--info-color)',
                  }}
                  onClick={() => handleCardClick(task.id)}
                >
                  {/* Card Header */}
                  <div className={styles.cardHeader}>
                    <div>
                      <div className={styles.taskId}>{task.taskNumber || task.id}</div>
                      <h4 className={styles.taskTitle}>{task.title}</h4>
                    </div>
                    <Badge variant={getPriorityBadgeVariant(task.priority)}>
                      <i className="fas fa-exclamation-circle" /> {getPriorityLabel(task.priority)}
                    </Badge>
                  </div>

                  {/* Description */}
                  <p className={styles.taskDescription}>{task.description}</p>

                  {/* Skills */}
                  {task.skillsRequired && task.skillsRequired.length > 0 && (
                    <div className={styles.skillsBadges}>
                      {task.skillsRequired.map((skill, idx) => (
                        <Badge key={idx} variant="primary">
                          <i className="fas fa-tools" /> {skill}
                        </Badge>
                      ))}
                    </div>
                  )}

                  {/* Metrics */}
                  <div className={styles.metricsGrid}>
                    <div className={styles.metricItem}>
                      <div className={styles.metricLabel}>HẠN CHỐT</div>
                      <div className={styles.metricValue}>
                        <i className="fas fa-clock" /> {formatSLATime(task.slaRemaining)}
                      </div>
                    </div>
                    <div className={styles.metricItem}>
                      <div className={styles.metricLabel}>ESTIMATE</div>
                      <div className={styles.metricValue}>
                        <i className="fas fa-hourglass-half" /> {task.estimatedHours}h
                      </div>
                    </div>
                    <div className={styles.metricItem}>
                      <div className={styles.metricLabel}>TRẠNG THÁI SLA</div>
                      <SLABadge
                        status={getSLAStatus(task.slaRemaining)}
                        timeRemaining={getSLAStatus(task.slaRemaining).toUpperCase()}
                      />
                    </div>
                    <div className={styles.metricItem}>
                      <div className={styles.metricLabel}>IN POOL</div>
                      <div className={styles.metricValue}>
                        <i className="fas fa-clock" /> {formatTimeInPool(task.createdAt)}
                      </div>
                    </div>
                  </div>

                  {/* Footer */}
                  <div className={styles.cardFooter}>
                    <i className="fas fa-clock" /> Đăng {formatTimeInPool(task.createdAt)} trước
                    bởi <strong>{task.creatorName}</strong>
                  </div>

                  {/* Action bar — slides in below card content on click */}
                  {expandedCardId === task.id && (
                    <div className={styles.cardActions} onClick={(e) => e.stopPropagation()}>
                      {currentUser?.id === task.creatorId ? (
                        <Badge variant="success">
                          <i className="fas fa-pen"></i> Bạn đã tạo
                        </Badge>
                      ) : (
                        <Button
                          variant={
                            task.priority === TaskPriority.Critical
                              ? 'danger'
                              : task.priority === TaskPriority.High
                              ? 'warning'
                              : 'primary'
                          }
                          onClick={() => handleOpenClaimModal(task)}
                        >
                          <i className="fas fa-hand-paper" /> Nhận công việc
                        </Button>
                      )}
                      <Button
                        variant="secondary"
                        onClick={() => handleViewDetails(task.id)}
                      >
                        <i className="fas fa-info-circle" /> Chi tiết
                      </Button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </TableCard>

      {/* Claim Task Modal */}
      {selectedTask && (
        <ClaimTaskModal
          task={selectedTask}
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          onConfirm={handleConfirmClaim}
          loading={claiming}
        />
      )}
    </div>
  );
};

export default TaskPoolPage;
