import React, { useState, useMemo } from 'react';
import { SLAAlertFilters, SLASeverity } from '../../../models/SLAAlert';
import { Select, SelectOption } from '../../common/Select';
import { useResponsive } from '../../../hooks/useResponsive';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './AlertsFilters.module.css';

interface AlertsFiltersProps {
  filters: SLAAlertFilters;
  onFiltersChange: (filters: SLAAlertFilters) => void;
}

const SEVERITY_BUTTONS: { value: SLASeverity | 'all'; label: string }[] = [
  { value: 'all',               label: 'Tất cả' },
  { value: SLASeverity.Breached, label: 'Vi phạm SLA' },
  { value: SLASeverity.Danger,   label: 'Nguy cơ cao' },
  { value: SLASeverity.Warning,  label: 'Cảnh báo' },
  { value: SLASeverity.Watch,    label: 'Theo dõi' },
];

export const AlertsFilters: React.FC<AlertsFiltersProps> = ({ filters, onFiltersChange }) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);
  const { departmentOptions, alertTypeOptions } = useFormOptions('alerts-filter');

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: 'all', label: 'Tất cả khoa/phòng' }, ...departmentOptions],
    [departmentOptions]
  );

  const allTypeOptions: SelectOption[] = useMemo(
    () => [{ value: 'all', label: 'Tất cả loại' }, ...alertTypeOptions],
    [alertTypeOptions]
  );

  const hasActiveFilters =
    filters.severity !== 'all' || filters.type !== 'all' || filters.departmentId !== 'all';
  const activeFilterCount =
    (filters.severity !== 'all' ? 1 : 0) +
    (filters.type !== 'all' ? 1 : 0) +
    (filters.departmentId !== 'all' ? 1 : 0);

  const handleSeverityChange = (severity: SLASeverity | 'all') => {
    onFiltersChange({ ...filters, severity });
  };

  const handleTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({ ...filters, type: e.target.value as SLAAlertFilters['type'] });
  };

  const handleDepartmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({ ...filters, departmentId: e.target.value });
  };

  const handleClear = () => {
    onFiltersChange({ severity: 'all', type: 'all', departmentId: 'all' });
    setIsExpanded(false);
  };

  // ─── Mobile ─────────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && <div className={styles.filterBackdrop} onClick={() => setIsExpanded(false)} />}
        <div className={styles.container}>
          <div className={styles.title}>Cảnh báo SLA</div>
          <div className={styles.filterDropdownWrapper}>
            <button
              className={styles.filterToggle}
              onClick={() => setIsExpanded((v) => !v)}
              aria-expanded={isExpanded}
              type="button"
            >
              <i className="fas fa-filter" />
              <span>Lọc</span>
              {activeFilterCount > 0 && (
                <span className={styles.filterBadge}>{activeFilterCount}</span>
              )}
              <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
            </button>
            {isExpanded && (
              <div className={styles.mobileFilters}>
                {/* Severity chips */}
                <div className={styles.chipGroup}>
                  {SEVERITY_BUTTONS.map((btn) => (
                    <button
                      key={btn.value}
                      type="button"
                      className={`${styles.chip} ${styles[`chip_${btn.value}`] ?? ''} ${filters.severity === btn.value ? styles.chipActive : ''}`}
                      onClick={() => handleSeverityChange(btn.value as SLASeverity | 'all')}
                    >
                      {btn.label}
                    </button>
                  ))}
                </div>
                <Select value={filters.type ?? 'all'} onChange={handleTypeChange} options={allTypeOptions} fullWidth />
                <Select value={filters.departmentId ?? 'all'} onChange={handleDepartmentChange} options={allDeptOptions} fullWidth />
                {hasActiveFilters && (
                  <button className={styles.clearFiltersButton} onClick={handleClear} type="button">
                    <i className="fas fa-times-circle" /> Xóa bộ lọc
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </>
    );
  }

  // ─── Desktop ─────────────────────────────────────────────────────────────────
  return (
    <div className={styles.container}>
      <div className={styles.title}>Cảnh báo SLA</div>
      <div className={styles.filters}>
        {/* Severity chips */}
        <div className={styles.chipGroup}>
          {SEVERITY_BUTTONS.map((btn) => (
            <button
              key={btn.value}
              type="button"
              className={`${styles.chip} ${styles[`chip_${btn.value}`] ?? ''} ${filters.severity === btn.value ? styles.chipActive : ''}`}
              onClick={() => handleSeverityChange(btn.value as SLASeverity | 'all')}
            >
              {btn.label}
            </button>
          ))}
        </div>
        <Select value={filters.type ?? 'all'} onChange={handleTypeChange} options={allTypeOptions} size="small" />
        <Select value={filters.departmentId ?? 'all'} onChange={handleDepartmentChange} options={allDeptOptions} size="small" />
        {hasActiveFilters && (
          <button className={styles.clearFiltersButtonDesktop} onClick={handleClear} type="button">
            <i className="fas fa-times-circle" /> Xóa bộ lọc
          </button>
        )}
      </div>
    </div>
  );
};
