import { UUID, Timestamps } from './common';

// ─────────────────────────────────────────────────────────────────────────────
// Enums
// ─────────────────────────────────────────────────────────────────────────────

export enum FallWarningProposalStatus {
  NotProposed = 'not_proposed',
  Proposed    = 'proposed',
}

export enum FallWarningCurrentStatus {
  NotFixed   = 'not_fixed',
  InProgress = 'in_progress',
  Fixed      = 'fixed',
}

// ─────────────────────────────────────────────────────────────────────────────
// Entity
// ─────────────────────────────────────────────────────────────────────────────

export interface FallLocationWarning extends Timestamps {
  id:                  UUID;
  locationCode:        string;     // VTN-YYYYMMDD-XXXX

  // ─── Survey info ────────────────────────────────────────────────────────
  surveyDate:          string;     // ISO date
  location:            string;     // Vị trí
  causes:              string[];   // Nguyên nhân (array)
  detailedDescription: string;     // Mô tả chi tiết
  preFixPhotoUrl:      string | null;
  proposedFix:         string;     // Đề xuất khắc phục
  proposalStatus:      FallWarningProposalStatus;

  // ─── Follow-up ────────────────────────────────────────────────────────
  reSurveyDate:        string | null;
  currentStatus:       FallWarningCurrentStatus;
  postFixPhotoUrl:     string | null;
  notes:               string | null;

  // ─── Metadata ─────────────────────────────────────────────────────────
  departmentId:        string | null;
  departmentName:      string;
  createdById:         UUID;
  createdByName:       string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Filters
// ─────────────────────────────────────────────────────────────────────────────

export interface FallLocationWarningFilters {
  search?:         string;
  currentStatus?:  FallWarningCurrentStatus | '';
  departmentId?:   string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Stats
// ─────────────────────────────────────────────────────────────────────────────

export interface FallLocationWarningStats {
  total:      number;
  notFixed:   number;
  inProgress: number;
  fixed:      number;
  proposed:   number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

export const createEmptyFallLocationWarning = (): Omit<FallLocationWarning, 'id' | 'locationCode' | 'createdAt' | 'updatedAt'> => ({
  surveyDate:          new Date().toISOString().split('T')[0],
  location:            '',
  causes:              [],
  detailedDescription: '',
  preFixPhotoUrl:      null,
  proposedFix:         '',
  proposalStatus:      FallWarningProposalStatus.NotProposed,
  reSurveyDate:        null,
  currentStatus:       FallWarningCurrentStatus.NotFixed,
  postFixPhotoUrl:     null,
  notes:               null,
  departmentId:        null,
  departmentName:      '',
  createdById:         '',
  createdByName:       '',
});
