import React from 'react';
import { TeamMember } from '../../../models/ManagerDashboard';
import styles from './TeamWorkload.module.css';

interface TeamWorkloadProps {
  teamMembers: TeamMember[];
}

export const TeamWorkload: React.FC<TeamWorkloadProps> = ({ teamMembers }) => {
  const getWorkloadColor = (percent: number): string => {
    if (percent >= 90) return 'danger';
    if (percent >= 70) return 'warning';
    return 'success';
  };

  const getWorkloadGradient = (percent: number): string => {
    if (percent >= 90) {
      return 'linear-gradient(90deg, var(--danger), #dc2626)';
    }
    if (percent >= 70) {
      return 'linear-gradient(90deg, var(--danger), var(--warning))';
    }
    return 'linear-gradient(90deg, var(--warning), var(--success))';
  };

  return (
    <div className={styles.teamWorkload}>
      {teamMembers.length === 0 ? (
        <div className={styles.emptyState}>
          <i className="fas fa-users" />
          <p>Chưa có dữ liệu khối lượng công việc nhóm</p>
        </div>
      ) : (
        teamMembers.map((member) => (
        <div key={member.id} className={styles.memberCard}>
          {/* Header with avatar and name */}
          <div className={styles.memberHeader}>
            <div className={styles.memberInfo}>
              <div
                className={styles.avatar}
                style={{ background: member.avatarGradient }}
              >
                {member.avatar}
              </div>
              <div className={styles.nameContainer}>
                <div className={styles.name}>{member.name}</div>
                <div className={styles.role}>{member.role}</div>
              </div>
            </div>
            <div className={styles.taskCount}>
              <div className={styles.taskNumber}>{member.taskCount}</div>
              <div className={styles.taskLabel}>tasks</div>
            </div>
          </div>

          {/* Workload progress bar */}
          <div className={styles.workloadBar}>
            <div className={styles.progressTrack}>
              <div
                className={styles.progressFill}
                style={{
                  width: `${member.workloadPercent}%`,
                  background: getWorkloadGradient(member.workloadPercent),
                }}
              />
            </div>
            <span
              className={`${styles.workloadPercent} ${
                styles[getWorkloadColor(member.workloadPercent)]
              }`}
            >
              {member.workloadPercent}%
            </span>
          </div>

          {/* Stats */}
          <div className={styles.stats}>
            <span className={styles.stat}>
              <i className="fas fa-star" style={{ color: 'var(--warning)' }} />{' '}
              {member.rating.toFixed(1)} Đánh giá
            </span>
            <span className={styles.statDivider}>|</span>
            <span className={styles.stat}>
              <i
                className="fas fa-check-circle"
                style={{ color: 'var(--success)' }}
              />{' '}
              {member.completedCount} Hoàn thành
            </span>
          </div>
        </div>
      )))
      }
    </div>
  );
};
