import React, { useState, useEffect } from 'react';
import { Workflow } from '../../models/Help';
import { helpService } from '../../services/helpService';
import { useAppToast } from '../../hooks/useAppToast';
import { WorkflowDiagram } from '../../components/help/WorkflowDiagram';
import { WorkflowStepsTable } from '../../components/help/WorkflowStepsTable';
import { EscalationRules } from '../../components/help/EscalationRules';
import { RolesMatrix } from '../../components/help/RolesMatrix';
import { AssignmentStrategies } from '../../components/help/AssignmentStrategies';
import styles from './WorkflowsPage.module.css';

const COMPARISON_ROWS = [
  { criteria: 'Mục đích', ticket: 'Giải quyết vấn đề, hỗ trợ khẩn cấp', task: 'Thực hiện công việc theo kế hoạch' },
  { criteria: 'Người khởi tạo', ticket: 'End User, Staff, Manager', task: 'Manager, Admin' },
  { criteria: 'Ai thực hiện', ticket: 'Staff (được assign bởi Manager)', task: 'Staff (assign hoặc self-pick)' },
  { criteria: 'SLA tracking', ticket: '✅ Strict SLA theo priority (Critical: 2h, High: 4h...)', task: '⚠️ Deadline-based, không strict SLA' },
  { criteria: 'Approval process', ticket: 'Manager/User review sau resolved', task: 'Manager review sau completion' },
  { criteria: 'Reassignment', ticket: 'Manager decision, cần lý do rõ ràng', task: 'Manager/Lead decision, flexible hơn' },
  { criteria: 'Phản hồi cuối', ticket: 'User rate 1-5 sao', task: 'Manager approve/reject/request changes' },
  { criteria: 'Escalation', ticket: '✅ Auto-escalate khi breach SLA', task: '⚠️ Manual escalate khi blocked lâu' },
];

const BEST_PRACTICES = [
  {
    audience: 'Cho End Users',
    badgeClass: styles.bpBadgeUser,
    wrapperClass: styles.bpUser,
    items: [
      { bold: 'Tạo ticket rõ ràng:', text: ' Tiêu đề ngắn gọn, mô tả chi tiết vấn đề' },
      { bold: 'Chọn priority đúng:', text: ' Critical chỉ dành cho cấp cứu, hệ thống sập' },
      { bold: 'Đính kèm hình ảnh:', text: ' Screenshot hoặc ảnh chụp giúp staff hiểu nhanh hơn' },
      { bold: 'Theo dõi thường xuyên:', text: ' Check status và reply comment kịp thời' },
    ],
  },
  {
    audience: 'Cho Staff',
    badgeClass: styles.bpBadgeStaff,
    wrapperClass: styles.bpStaff,
    items: [
      { bold: 'Update tiến độ thường xuyên:', text: ' Ít nhất 1 lần/4h cho tasks đang làm' },
      { bold: 'Communicate proactively:', text: ' Báo sớm khi gặp vướng mắc' },
      { bold: 'Log hours accurately:', text: ' Ghi nhận giờ làm chính xác cho reporting' },
      { bold: 'Check subtasks:', text: ' Đánh dấu hoàn thành từng phần để manager track được' },
    ],
  },
  {
    audience: 'Cho Managers/Leads',
    badgeClass: styles.bpBadgeManager,
    wrapperClass: styles.bpManager,
    items: [
      { bold: 'Triage nhanh:', text: ' Respond ticket trong SLA time' },
      { bold: 'Assign phù hợp:', text: ' Cân nhắc workload và skill của staff' },
      { bold: 'Monitor proactively:', text: ' Theo dõi dashboard, không chờ escalation' },
      { bold: 'Review công bằng:', text: ' Đánh giá dựa trên kết quả' },
      { bold: 'Document decisions:', text: ' Ghi rõ lý do khi reject/reassign' },
    ],
  },
];

export const WorkflowsPage: React.FC = () => {
  const [workflows, setWorkflows] = useState<Workflow[]>([]);
  const [selectedWorkflow, setSelectedWorkflow] = useState<Workflow | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const toast = useAppToast();

  useEffect(() => {
    const timer = setTimeout(() => { loadWorkflows(); }, 0);
    return () => clearTimeout(timer);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const loadWorkflows = async () => {
    try {
      setLoading(true);
      setError(null);
      const summaries = await helpService.getWorkflows();
      setWorkflows(summaries);
      if (summaries.length > 0) {
        // Load full workflow detail (with steps, escalation rules, roles matrix, etc.)
        const fullWf = await helpService.getWorkflow(summaries[0].type as 'ticket' | 'task');
        setSelectedWorkflow(fullWf);
      }
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể tải quy trình. Vui lòng thử lại.');
      setError('Không thể tải quy trình. Vui lòng thử lại.');
    } finally {
      setLoading(false);
    }
  };

  const handleSelectWorkflow = async (wf: Workflow) => {
    try {
      const fullWf = await helpService.getWorkflow(wf.type as 'ticket' | 'task');
      setSelectedWorkflow(fullWf);
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể tải quy trình. Vui lòng thử lại.');
    }
  };

  if (loading) return <div className={styles.workflowsPage}><div className={styles.loading}><i className="fas fa-spinner fa-spin"></i> Đang tải...</div></div>;
  if (error) return (
    <div className={styles.workflowsPage}>
      <div className={styles.error}>
        <i className="fas fa-exclamation-circle"></i>
        <p>{error}</p>
        <button className={styles.retryButton} onClick={loadWorkflows}>
          <i className="fas fa-redo"></i> Thử lại
        </button>
      </div>
    </div>
  );
  if (workflows.length === 0) return <div className={styles.workflowsPage}><div className={styles.empty}>Không có quy trình nào</div></div>;

  return (
    <div className={styles.workflowsPage}>
      {/* Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>Quy trình làm việc</h1>
        <p className={styles.subtitle}>Tìm hiểu các quy trình xử lý ticket và task trong hệ thống</p>
      </div>

      {/* Overview Card */}
      <div className={styles.overviewCard}>
        <h2 className={styles.overviewTitle}>ℹ️ Giới thiệu</h2>
        <p className={styles.overviewText}>Hệ thống QLCV Y Khoa có <strong>2 quy trình làm việc chính</strong>:</p>
        <ol className={styles.overviewList}>
          <li><strong>Support Ticket Management</strong> – Quản lý yêu cầu hỗ trợ từ người dùng</li>
          <li><strong>Task Assignment &amp; Management</strong> – Giao việc và theo dõi tiến độ công việc</li>
        </ol>
        <p className={styles.overviewNote}>ℹ️ Mỗi quy trình có các bước rõ ràng, phân quyền chi tiết và SLA tracking tự động.</p>
      </div>

      {/* Tabs + Per-Workflow Content */}
      <div className={styles.card}>
        <div className={styles.tabs}>
          {workflows.map((wf) => (
            <button
              key={wf.id}
              className={`${styles.tab} ${selectedWorkflow?.id === wf.id ? styles.tabActive : ''}`}
              onClick={() => handleSelectWorkflow(wf)}
            >
              {wf.type === 'ticket' ? '🎫' : '📋'} {wf.name}
            </button>
          ))}
        </div>

        {selectedWorkflow && (
          <div className={styles.content}>
            <h2 className={styles.workflowTitle}>{selectedWorkflow.title}</h2>
            <p className={styles.workflowDesc}>{selectedWorkflow.description}</p>

            {/* Department Note (ticket only) */}
            {selectedWorkflow.departmentNote && (
              <div className={styles.deptNoteBox}>
                <h4 className={styles.deptNoteTitle}>🏥 Mô hình Khoa/Phòng</h4>
                {selectedWorkflow.departmentNote.map((line, i) => (
                  <p key={i} className={styles.deptNoteLine}>• {line}</p>
                ))}
              </div>
            )}

            {/* Diagram */}
            <section className={styles.section}>
              <h3 className={styles.sectionTitle}>Sơ đồ quy trình</h3>
              <WorkflowDiagram diagramCode={selectedWorkflow.diagram} type={selectedWorkflow.type} />
            </section>

            {/* Steps */}
            <section className={styles.section}>
              <h3 className={styles.sectionTitle}>Chi tiết các bước</h3>
              <WorkflowStepsTable steps={selectedWorkflow.steps} />
            </section>

            {/* SLA Escalation (ticket only) */}
            {selectedWorkflow.slaEscalation && selectedWorkflow.slaEscalation.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>⚡ Quy tắc Escalation SLA</h3>
                <EscalationRules
                  slaEscalation={selectedWorkflow.slaEscalation}
                  note={selectedWorkflow.slaEscalationNote}
                />
              </section>
            )}

            {/* Roles Matrix */}
            {selectedWorkflow.rolesMatrix && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>🔐 Ma trận phân quyền</h3>
                <RolesMatrix matrix={selectedWorkflow.rolesMatrix} />
              </section>
            )}

            {/* Assignment Strategies (task only) */}
            {selectedWorkflow.assignmentStrategies && selectedWorkflow.assignmentStrategies.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>📊 So sánh 3 chiến lược giao việc</h3>
                <AssignmentStrategies strategies={selectedWorkflow.assignmentStrategies} />
              </section>
            )}

            {/* Progress Tracking (task only) */}
            {selectedWorkflow.progressTracking && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>📈 Progress Tracking</h3>
                <div className={styles.progressBox}>
                  {selectedWorkflow.progressTracking.items.map((item, i) => (
                    <p key={i} className={styles.progressItem}>• {item}</p>
                  ))}
                  {selectedWorkflow.progressTracking.note && (
                    <p className={styles.progressNote}>{selectedWorkflow.progressTracking.note}</p>
                  )}
                </div>
              </section>
            )}

            {/* Meta */}
            <div className={styles.meta}>
              Cập nhật lần cuối: {new Date(selectedWorkflow.lastUpdated).toLocaleDateString('vi-VN')}
            </div>
          </div>
        )}
      </div>

      {/* Comparison Card */}
      <div className={styles.comparisonCard}>
        <h2 className={styles.cardSectionTitle}>⚖️ So sánh 2 Workflows</h2>
        <div className={styles.tableWrapper}>
          <table className={styles.compTable}>
            <thead>
              <tr>
                <th>Tiêu chí</th>
                <th>Support Tickets</th>
                <th>Tasks</th>
              </tr>
            </thead>
            <tbody>
              {COMPARISON_ROWS.map((row, i) => (
                <tr key={i}>
                  <td><strong>{row.criteria}</strong></td>
                  <td>{row.ticket}</td>
                  <td>{row.task}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Best Practices Card */}
      <div className={styles.bestPracticesCard}>
        <h2 className={styles.cardSectionTitle}>💡 Best Practices</h2>
        <div className={styles.bpGrid}>
          {BEST_PRACTICES.map((group, i) => (
            <div key={i} className={`${styles.bpBox} ${group.wrapperClass}`}>
              <h4 className={styles.bpBoxTitle}>
                <span className={`${styles.bpBadge} ${group.badgeClass}`}>{group.audience}</span>
              </h4>
              <ul className={styles.bpList}>
                {group.items.map((item, j) => (
                  <li key={j}><strong>{item.bold}</strong>{item.text}</li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};
