import React from 'react';
import {
  FallLocationWarning,
  FallWarningCurrentStatus,
  FallWarningProposalStatus,
} from '../../../models/FallLocationWarning';
import { Button } from '../../../components/common/Button';

interface Props {
  items:    FallLocationWarning[];
  loading?: boolean;
  onEdit:   (item: FallLocationWarning) => void;
  onDelete: (item: FallLocationWarning) => void;
}

const STATUS_LABEL: Record<FallWarningCurrentStatus, { label: string; color: string }> = {
  [FallWarningCurrentStatus.NotFixed]:   { label: 'Chưa khắc phục', color: '#ef4444' },
  [FallWarningCurrentStatus.InProgress]: { label: 'Đang khắc phục', color: '#f59e0b' },
  [FallWarningCurrentStatus.Fixed]:      { label: 'Đã khắc phục',   color: '#10b981' },
};

const PROPOSAL_LABEL: Record<FallWarningProposalStatus, { label: string; color: string }> = {
  [FallWarningProposalStatus.NotProposed]: { label: 'Chưa đề xuất', color: '#94a3b8' },
  [FallWarningProposalStatus.Proposed]:    { label: 'Đã đề xuất',   color: '#3b82f6' },
};

const StatusBadge: React.FC<{ status: FallWarningCurrentStatus }> = ({ status }) => {
  const cfg = STATUS_LABEL[status] ?? { label: status, color: '#94a3b8' };
  return (
    <span style={{ padding: '2px 8px', borderRadius: 12, background: cfg.color + '20', color: cfg.color, fontSize: '0.75rem', fontWeight: 600 }}>
      {cfg.label}
    </span>
  );
};

const ProposalBadge: React.FC<{ status: FallWarningProposalStatus }> = ({ status }) => {
  const cfg = PROPOSAL_LABEL[status] ?? { label: status, color: '#94a3b8' };
  return (
    <span style={{ padding: '2px 8px', borderRadius: 12, background: cfg.color + '20', color: cfg.color, fontSize: '0.75rem', fontWeight: 600 }}>
      {cfg.label}
    </span>
  );
};

export const FallWarningTable: React.FC<Props> = ({ items, loading, onEdit, onDelete }) => {
  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
        <i className="fas fa-spinner fa-spin" /> Đang tải...
      </div>
    );
  }

  if (!items.length) {
    return (
      <div style={{ textAlign: 'center', padding: '40px', color: '#94a3b8' }}>
        <i className="fas fa-inbox" style={{ fontSize: '2rem', display: 'block', marginBottom: 8 }} />
        Chưa có cảnh báo vị trí té ngã nào
      </div>
    );
  }

  return (
    <div style={{ overflowX: 'auto' }}>
      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #e2e8f0', background: '#f8fafc' }}>
            <th style={th}>Mã</th>
            <th style={th}>Vị trí</th>
            <th style={th}>Ngày khảo sát</th>
            <th style={th}>Trạng thái</th>
            <th style={th}>Đề xuất</th>
            <th style={th}>Khoa</th>
            <th style={th}>Người tạo</th>
            <th style={th}>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => (
            <tr key={item.id} style={{ borderBottom: '1px solid #e2e8f0' }}>
              <td style={td}><code style={{ fontSize: '0.75rem', color: '#3b82f6' }}>{item.locationCode}</code></td>
              <td style={td}>{item.location}</td>
              <td style={td}>{item.surveyDate ? new Date(item.surveyDate).toLocaleDateString('vi-VN') : '—'}</td>
              <td style={td}><StatusBadge status={item.currentStatus} /></td>
              <td style={td}><ProposalBadge status={item.proposalStatus} /></td>
              <td style={td}>{item.departmentName || '—'}</td>
              <td style={td}>{item.createdByName}</td>
              <td style={td}>
                <div style={{ display: 'flex', gap: 4 }}>
                  <Button variant="secondary" onClick={() => onEdit(item)}>
                    <i className="fas fa-edit" />
                  </Button>
                  <Button variant="danger" onClick={() => onDelete(item)}>
                    <i className="fas fa-trash" />
                  </Button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

const th: React.CSSProperties = {
  padding: '10px 12px',
  textAlign: 'left',
  fontWeight: 600,
  color: '#475569',
  whiteSpace: 'nowrap',
};

const td: React.CSSProperties = {
  padding: '10px 12px',
  color: '#1e293b',
  verticalAlign: 'middle',
};
