import React from 'react';
import { FallLocationWarningFilters, FallWarningCurrentStatus } from '../../../models/FallLocationWarning';

interface Props {
  filters:  FallLocationWarningFilters;
  onChange: (f: FallLocationWarningFilters) => void;
  onClear:  () => void;
}

const STATUS_OPTIONS = [
  { value: '',           label: 'Tất cả trạng thái' },
  { value: FallWarningCurrentStatus.NotFixed,   label: 'Chưa khắc phục' },
  { value: FallWarningCurrentStatus.InProgress, label: 'Đang khắc phục' },
  { value: FallWarningCurrentStatus.Fixed,      label: 'Đã khắc phục'   },
];

export const FallWarningFiltersBar: React.FC<Props> = ({ filters, onChange, onClear }) => {
  const has = !!(filters.search || filters.currentStatus || filters.departmentId);

  return (
    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', padding: '8px 0' }}>
      <input
        type="text"
        placeholder="Tìm theo vị trí, mã..."
        value={filters.search ?? ''}
        onChange={(e) => onChange({ ...filters, search: e.target.value || undefined })}
        style={{ flex: 1, minWidth: 180, padding: '6px 10px', borderRadius: 6, border: '1px solid #d1d5db' }}
      />
      <select
        value={filters.currentStatus ?? ''}
        onChange={(e) => onChange({ ...filters, currentStatus: (e.target.value as FallWarningCurrentStatus) || undefined })}
        style={{ padding: '6px 10px', borderRadius: 6, border: '1px solid #d1d5db' }}
      >
        {STATUS_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
      {has && (
        <button
          onClick={onClear}
          style={{ padding: '6px 12px', borderRadius: 6, border: '1px solid #d1d5db', background: '#fff', cursor: 'pointer' }}
        >
          <i className="fas fa-times" /> Xóa bộ lọc
        </button>
      )}
    </div>
  );
};
